const savedCart=read('miglik.showcase.cart',[]);
const state={catalog:null,session:null,cart:(Array.isArray(savedCart)?savedCart:[]).map(item=>({...item,clientId:item.clientId||crypto.randomUUID()})),draft:draftsAllowed()?read('miglik.draft',null):null,draftChanged:false,step:'frame',selected:'',partCategory:'hair',quantity:(savedEdit?.type==='custom'?savedEdit.quantity:(draftsAllowed()?read('miglik.builderQuantity',1):1))||1,cartEditId:savedEdit?.id||null,cartEditMode:savedEdit?.type||null,cartEditProductId:savedEdit?.productId||null,quote:null,quoteError:'',filter:'all',search:'',adminTab:'orders',adminData:null,adminOrderScope:'active',adminOrderPage:1,adminOrderSearch:'',adminOrders:null,productVariant:savedEdit?.variantId||'',productQty:savedEdit?.quantity||1,promo:'',projects:[],orders:[],authEmail:'',authChallenge:'',authResendAt:0,mobileMenu:false};
