const discountHint=()=>state.catalog.settings.discounts.filter(r=>r.percent>0).map(r=>`От ${r.min} копий −${r.percent}%`).join(' · ')||'Стоимость по базовой цене';
const occasions={all:'Все подарки',love:'Для двоих',family:'Для семьи',birthday:'День рождения',wedding:'Свадьба',anniversary:'Годовщина','new-year':'Новый год',colleagues:'Коллегам','february-14':'14 февраля','march-8':'8 Марта','february-23':'23 февраля',corporate:'Корпоративные'};
