const app=document.querySelector('#app');
function focusContent(){const main=app.querySelector('main');if(main){main.id='main-content';main.tabIndex=-1;main.focus({preventScroll:true});}}
function restoreControl(button){const {action,id='',delta=''}=button.dataset;[...app.querySelectorAll('[data-action]')].find(el=>el.dataset.action===action&&(el.dataset.id||'')===id&&(el.dataset.delta||'')===delta)?.focus({preventScroll:true});}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),4500);}
const api=previewApi;
function persist(){localStorage.setItem('miglik.showcase.cart',JSON.stringify(state.cart));if(draftsAllowed()){if(state.draft)localStorage.setItem('miglik.draft',JSON.stringify(state.draft));localStorage.setItem('miglik.builderQuantity',JSON.stringify(state.quantity));}if(state.cartEditId)localStorage.setItem('miglik.showcase.cartEdit',JSON.stringify({id:state.cartEditId,type:state.cartEditMode,productId:state.cartEditProductId,variantId:state.productVariant,quantity:state.cartEditMode==='product'?state.productQty:state.quantity}));else localStorage.removeItem('miglik.showcase.cartEdit');}
async function nav(path){if(route==='/builder')persist();const targetPath=new URL(path,location.origin).pathname,editorPath=state.cartEditMode==='product'?'/product/'+state.cartEditProductId:'/builder';if(state.cartEditId&&route===editorPath&&targetPath!==editorPath){clearCartEdit();persist();}if(targetPath==='/'){location.href=previewURL(path);return;}history.pushState({},'',previewURL(path));route=targetPath;state.quote=null;state.quoteError='';closeModal();window.scrollTo({top:0,left:0,behavior:'instant'});await loadRoute();focusContent();}
function getProductConfig(p,variant=p.variants[0]){return variant.config||demoConfig(state.catalog,{size:variant.size,color:variant.color,background:p.background,count:p.count,title:p.name});}
function testBadge(){return '<span class="test-label">Тестовый образец</span>';}
function rememberCatalog() {
  if (route !== '/catalog' && !route.startsWith('/gifts/')) return;
  history.replaceState({ ...history.state, catalogView: { filter: state.filter, search: state.search } }, '');
}
function restoreCatalog() {
  const view = history.state?.catalogView;
  if (!view) return;
  state.filter = typeof view.filter === 'string' ? view.filter : 'all';
  state.search = typeof view.search === 'string' ? view.search : '';
}
function photoWithHeroes(product, photo) {
  const heroes = photo.heroes.map(hero => `<a class="gift-hero gift-hero--${hero.align}" href="${giftStudioURL(product.id, hero.number)}" data-native
    style="--edge:${hero.edge}%;--top:${hero.top}%;--hero-width:${hero.width}%;--hero-height:${hero.height}%"
    aria-label="${esc(hero.label)} в рамке «${esc(product.name)}»: открыть конструктор">
    <span class="gift-hero-marker" aria-hidden="true">✎</span>
  </a>`).join('');
  return `<div class="gift-photo-stage" style="--photo-ratio:${photo.width}/${photo.height}">
    <img src="${photo.image}" srcset="${photo.srcset}" sizes="(max-width:767px) calc(100vw - 40px), (max-width:1024px) 44vw, 420px"
      width="${photo.width}" height="${photo.height}" alt="${esc(photo.alt)}" loading="lazy" decoding="async">
    ${heroes}
  </div>`;
}
function productCard(product, index = 0) {
  const photo = Object.hasOwn(giftPhotos, product.id) ? giftPhotos[product.id] : null;
  const art = photo ? photoWithHeroes(product, photo) : scene(getProductConfig(product), state.catalog);
  const count = product.count;
  const sizes = [...new Set(product.variants.map(variant => variant.size))].join(' / ');
  const price = money(Math.min(...product.variants.map(variant => variant.price)));
  return `<article class="product-card${photo ? ' product-card--photo' : ''}">
    <div class="product-art palette-${index % 4}">${art}
      ${product.demo ? testBadge() : ''}
      <span class="product-card-category">${esc(occasions[product.category] || 'Подарок MIGLIK')}</span>
      ${photo ? '' : '<span class="gift-sketch-label">Эскиз</span>'}
    </div>
    ${photo ? `<div class="gift-photo-help">
      <p>Нажмите на фигурку, чтобы настроить героя.</p>
      <a href="${giftStudioURL(product.id)}" data-native>Настроить героев <span aria-hidden="true">↗</span></a>
    </div>` : ''}
    <div class="product-meta"><span>${count} ${count === 1 ? 'персонаж' : count < 5 ? 'персонажа' : 'персонажей'}</span><span>${esc(sizes)}</span></div>
    <h3>${esc(product.name)}</h3>
    <div class="card-buy-row"><strong>от ${price}</strong>
      <a class="card-select" href="/product/${esc(product.id)}" aria-label="Выбрать подарок «${esc(product.name)}»">Выбрать подарок ${icon('chevron')}</a>
    </div>
  </article>`;
}
function brand(){return 'MIGLIK<span class="brand-mark" aria-hidden="true">'+(route==='/builder'?'':'.')+'</span>';}
function header(){const quantity=state.cart.reduce((s,l)=>s+l.quantity,0);return `<div class="test-strip"><span>Демонстрация магазина · тестовые товары и цены</span></div><header class="site-header"><a class="wordmark" href="/" aria-label="MIGLIK — главная">${brand()}</a><nav class="desktop-nav"><a href="/catalog" class="${route==='/catalog'?'active':''}">Готовые подарки</a><a href="/how">Как заказать</a><a href="/#stories" data-native>Истории</a></nav><div class="header-actions"><a href="/account" class="icon-btn" aria-label="Личный кабинет">${icon('user')}</a><a href="/cart" class="icon-btn cart-icon" aria-label="Корзина: ${quantity}">${icon('bag')}${quantity?`<span>${quantity}</span>`:''}</a><a href="https://alinageminivolsip-ai.github.io/Mini-Brick-Studio/studio/" data-native class="btn btn-primary header-create">Создать подарок ${icon('plus')}</a><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Меню" aria-expanded="${state.mobileMenu}" aria-controls="mobile-navigation">${icon('menu')}</button></div></header>${state.mobileMenu?'<nav id="mobile-navigation" class="mobile-nav"><a href="/catalog">Готовые подарки</a><a href="https://alinageminivolsip-ai.github.io/Mini-Brick-Studio/studio/" data-native>Создать подарок</a><a href="/how">Как заказать</a><a href="/#stories" data-native>Истории</a></nav>':''}`;}
function footer(){return `<footer class="site-footer"><div class="footer-top"><div><a href="/" class="wordmark">${brand()}</a><p>Мгновения, которые остаются.</p><a class="footer-create" href="https://alinageminivolsip-ai.github.io/Mini-Brick-Studio/studio/" data-native>Создать свою историю ${icon('plus')}</a></div><div><b>Подарки</b><a href="https://alinageminivolsip-ai.github.io/Mini-Brick-Studio/studio/" data-native>Конструктор</a><a href="/catalog">Готовая коллекция</a><a href="/#stories" data-native>Галерея идей</a></div><div><b>Покупателям</b><a href="/how">Как заказать</a><a href="/delivery">Доставка и оплата</a><a href="/contacts" data-native>Контакты</a><a href="/returns" data-native>Возврат</a><a href="/#faq" data-native>Частые вопросы</a><a href="/legal" data-native>Документы</a></div><div><b>MIGLIK</b><a href="/about">О бренде</a><a href="/legal" data-native>Правовые документы</a><a href="/account">Личный кабинет</a></div></div><div class="footer-bottom"><span>© MIGLIK, 2026</span><span>Подарки с личным смыслом</span><a href="/privacy" data-native>Конфиденциальность</a><button type="button" class="text-button" data-action="cookie-settings">Cookie и память браузера</button></div></footer>`;}
function frameExamplePrice(frame){const config=demoConfig(state.catalog,{size:frame.id,count:2});return frame.price+(state.catalog.colors.find(c=>c.id===config.color)?.price||0)+(state.catalog.backgrounds.find(b=>b.id===config.background)?.price||0)+config.characters.reduce((sum,c)=>sum+Object.values(c.parts).reduce((subtotal,id)=>subtotal+(state.catalog.parts.find(p=>p.id===id)?.price||0),0),0);}
function home(){const sample=demoConfig(state.catalog,{size:'S',count:2,title:'Это мы'});return `<main class="home"><section class="home-hero wrap"><div class="hero-copy"><div class="hero-kicker">${icon('frame')} Персональные подарки с минифигурками</div><h1>Подарок,<br>в котором<br>узнают себя.</h1><p>Ваши люди, любимые детали и важные слова — в одной объёмной рамке.</p><div class="hero-buttons"><a class="btn btn-yellow" href="https://alinageminivolsip-ai.github.io/Mini-Brick-Studio/studio/" data-native>Создать свой подарок ${icon('plus')}</a><a class="btn btn-outline" href="/catalog">Выбрать готовый</a></div><div class="hero-options"><span>${icon('check')} 4 размера рамок</span><span>${icon('check')} Ваша надпись</span></div></div><div class="hero-display"><img class="hero-product-image" src="/assets/hero-v2.webp" alt="Визуализация белой объёмной рамки с двумя минифигурками и сердцем" fetchpriority="high" width="1024" height="1024"><div class="hero-personal"><span>${icon('heart')}</span><div><b>Соберите похожих на себя</b><small>Причёски, одежда, аксессуары</small></div></div><span class="image-note">Визуализация концепции MIGLIK</span></div></section><section class="shop-benefits wrap"><div>${icon('user')}<span>Персонажи,<br><b>похожие на вас</b></span></div><div>${icon('frame')}<span>Глубокая рамка<br><b>для вашей истории</b></span></div><div>${icon('heart')}<span>Имена, даты<br><b>и важные слова</b></span></div><div>${icon('copy')}<span>Несколько копий<br><b>со скидкой</b></span></div></section><section class="section wrap recipients"><div class="section-heading"><div><h2>Кому подарим?</h2><p>Выберите повод. Или создайте свой.</p></div></div><div class="occasion-row">${[['love','heart','Любимым'],['family','user','Семье'],['birthday','spark','Имениннику'],['wedding','frame','Молодожёнам'],['colleagues','bag','Коллегам']].map(([id,ic,label],i)=>`<a href="/gifts/${id}" class="occasion occasion-${i}"><span>${icon(ic)}</span><b>${label}</b>${icon('chevron')}</a>`).join('')}</div></section><section class="section wrap home-collection"><div class="section-heading"><div><h2>Истории, которые можно подарить</h2><p>Готовые композиции — выбирайте размер, цвет и количество.</p></div><a href="/catalog" class="btn btn-outline">Весь каталог ${icon('arrow')}</a></div><div class="product-grid home-products">${state.catalog.products.slice(0,3).map(productCard).join('')}</div></section><section class="section wrap sizes-section"><div class="section-heading"><div><h2>Каждой истории — своя рамка</h2><p>Четыре размера. Цена примера — за рамку с двумя тестовыми персонажами.</p></div><a href="https://alinageminivolsip-ai.github.io/Mini-Brick-Studio/studio/" data-native class="text-link">Выбрать размер ${icon('arrow')}</a></div><div class="home-sizes">${state.catalog.frames.map(f=>`<a href="https://alinageminivolsip-ai.github.io/Mini-Brick-Studio/studio/" data-native data-start-size="${esc(f.id)}" class="home-size"><div class="size-outline" style="--ratio:${f.width}/${f.height};--size:${f.id==='S'?'64':f.id==='M'?'94':f.id==='L'?'102':'118'}px"></div><b>${esc(f.id)}</b><span>${f.width} × ${f.height} мм</span><span class="home-size-price">от ${money(frameExamplePrice(f))}</span><span class="home-size-action">Выбрать размер ${icon('chevron')}</span></a>`).join('')}</div></section><section class="creator-feature wrap"><div class="creator-example"><div class="mini-step">Выберите детали — посмотрите результат</div><div class="creator-composition">${scene(sample,state.catalog)}</div><div class="detail-picks"><span class="pick-blue">Причёска</span><span class="pick-pink">Любимый свитер</span><span class="pick-yellow">Ваши слова</span></div></div><div class="creator-copy"><span class="creator-tag">Конструктор MIGLIK</span><h2>У вас есть история.<br>Давайте её соберём.</h2><p>Добавьте близких людей. Найдите знакомые детали. Выберите фон и напишите то, что хочется сохранить.</p><div class="creator-steps"><div><span>1</span><b>Выберите рамку</b></div><div><span>2</span><b>Соберите персонажей</b></div><div><span>3</span><b>Добавьте фон и слова</b></div></div><a href="https://alinageminivolsip-ai.github.io/Mini-Brick-Studio/studio/" data-native class="btn btn-primary">Открыть конструктор ${icon('plus')}</a></div></section><section class="home-bottom-cta"><div class="wrap"><div><h2>Подарите человеку<br>его маленький мир.</h2><p>Начните с рамки. Самое важное добавите вы.</p></div><a href="https://alinageminivolsip-ai.github.io/Mini-Brick-Studio/studio/" data-native class="btn btn-yellow">Создать подарок ${icon('plus')}</a></div></section></main>`;}

function catalog(){const theme=route.startsWith('/gifts/')?route.split('/').pop():null,filter=theme||state.filter;const products=state.catalog.products.filter(p=>(filter==='all'||p.category===filter)&&(!state.search||(p.name+' '+p.description).toLowerCase().includes(state.search.toLowerCase())));return `<main class="wrap page"><div class="breadcrumbs"><a href="/">Главная</a> / ${theme?'Подарки по поводу':'Каталог'}</div><div class="catalog-intro"><div class="eyebrow">Готовая коллекция</div><h1>${theme?esc(occasions[theme]||'Особенные подарки'):'Истории, которые можно подарить.'}</h1><p>${theme?themeText(theme):'Объёмная рамка, минифигурки и ваши важные детали. Выберите композицию — размер и цвет можно изменить.'}</p></div><div class="catalog-tools"><div class="pills">${['all','love','family','birthday','wedding','new-year','colleagues'].map(k=>`<button aria-pressed="${filter===k}" class="pill ${filter===k?'selected':''}" data-action="filter" data-id="${k}">${occasions[k]}</button>`).join('')}</div><label class="search">${icon('search')}<input id="catalog-search" placeholder="Найти подарок" value="${esc(state.search)}" aria-label="Поиск подарка"></label></div>${state.catalog.products.some(p=>p.demo)?'<div class="soft-notice">Тестовые композиции и цены. Реальные заказы пока не принимаются.</div>':''}<div class="product-grid">${products.map(productCard).join('')||'<div class="empty"><h2>Пока нет готовых композиций для этого повода</h2><p>Попробуйте выбрать другой повод или соберите свою композицию.</p><a class="btn btn-dark" href="https://alinageminivolsip-ai.github.io/Mini-Brick-Studio/studio/" data-native>В конструктор</a></div>'}</div>${frameGuide()}<div class="catalog-help"><span>Не нашли ту самую?</span><a href="https://alinageminivolsip-ai.github.io/Mini-Brick-Studio/studio/" data-native>Соберите подарок сами ${icon('arrow')}</a></div></main>`;}
function frameGuide(){
 const ids=new Set(state.catalog.products.flatMap(p=>p.variants.map(v=>v.size)));
 const frames=state.catalog.frames.filter(f=>ids.has(f.id));
 if(!frames.length)return '';
 return `<section class="frame-guide" aria-labelledby="frame-guide-title"><div class="eyebrow">Размеры и материалы</div><h2 id="frame-guide-title">Рамка для вашей истории.</h2><p>В карточке подарка можно сравнить доступные размеры, цвета и цену каждого варианта.</p><ul>${frames.map(f=>`<li><span class="frame-outline" style="--frame-ratio:${f.width}/${f.height}" aria-hidden="true"></span><b>${esc(f.id)}</b><span>${f.width} × ${f.height} мм</span><small>Глубина: ${f.depth} мм</small></li>`).join('')}</ul></section>`;
}
function themeText(theme){return {love:'Для двоих, у которых есть свои шутки, любимые места и общие мгновения.',family:'Мама, папа, дети и ваши большие семейные истории в одной рамке.',birthday:'Подарок, который похож на своего получателя. С любимыми деталями и личным смыслом.',wedding:'Чтобы сохранить начало общей истории и самые важные слова.',anniversary:'Годы вместе складываются из мгновений. Сохраните одно из них.','new-year':'Тёплые истории о людях, с которыми хочется встречать новый год.',colleagues:'Для людей, с которыми обычный рабочий день становится особенным.',corporate:'Композиции для команд. Скидка рассчитывается на копии одного варианта.'}[theme]||'Сохраните особенный повод в объёмной композиции MIGLIK.';}
function quantityControl(value,action='quantity',id=''){return `<div class="quantity"><button type="button" data-action="${action}" data-delta="-1" data-id="${esc(id)}" aria-label="Уменьшить количество">${icon('minus')}</button><input type="number" min="1" max="${state.catalog.settings.maxQuantity}" value="${value}" data-qty="${esc(id)}" data-quantity-action="${action}" aria-label="Количество копий"><button type="button" data-action="${action}" data-delta="1" data-id="${esc(id)}" aria-label="Увеличить количество">${icon('plus')}</button></div>`;}
function priceSummary(quote,compact=false){if(!quote)return `<div class="muted">${esc(state.quoteError||'Рассчитываем стоимость…')}</div>`;return `<div class="price-summary ${compact?'compact':''}"><div><span>Без скидки</span><span>${money(quote.before)}</span></div><div class="saving"><span>Экономия${quote.lines?.length===1?' · '+quote.lines[0].discount+'%':''}</span><span>−${money(quote.saving)}</span></div><div class="total"><b>Итого</b><b>${money(quote.total)}</b></div>${quote.lines?.length===1?`<small>${money(quote.lines[0].discountedUnit)} за копию с учётом скидки</small>`:''}</div>`;}
function product(){const p=state.catalog.products.find(p=>p.id===route.split('/').pop());if(!p)return empty('Подарок не найден','Вернуться к коллекции','/catalog');const v=p.variants.find(v=>v.id===state.productVariant)||p.variants[0];state.productVariant=v.id;const customPreview=hasGiftPreview(p.id),frame=state.catalog.frames.find(f=>f.id===v.size);return `<main class="wrap page"><div class="breadcrumbs"><a href="/">Главная</a> / <a href="/catalog">Подарки</a> / ${esc(p.name)}</div><div class="product-detail"><div class="detail-art palette-1${customPreview ? ' detail-art--gift' : ''}">${customPreview ? giftPreview(p,v,frame) : p.photoId?`<img src="/files/${esc(p.photoId)}" alt="${esc(p.name)}">`:scene(getProductConfig(p,v),state.catalog)}${p.demo?testBadge():''}</div><div class="detail-copy">${state.cartEditId&&state.cartEditMode==='product'?'<div class="soft-notice small">Редактируете подарок из корзины. <button class="text-button" data-action="cart-cancel-edit">Отменить правки</button></div>':''}<div class="eyebrow">${esc(occasions[p.category]||'MIGLIK')}</div><h1>${esc(p.name)}</h1><p>${esc(p.description)}</p><div class="detail-price">${money(v.price)} <span>за одну рамку</span></div><div class="label" id="size-label">Размер рамки</div><div class="size-options" role="group" aria-labelledby="size-label">${[...new Set(p.variants.map(v=>v.size))].map(s=>{const f=state.catalog.frames.find(f=>f.id===s);return `<button aria-pressed="${s===v.size}" data-action="product-size" data-id="${s}" class="size-option ${s===v.size?'selected':''}"><b>${s}</b><small>${f.width}×${f.height} мм</small></button>`;}).join('')}</div><div class="label" id="color-label">Цвет: ${esc(state.catalog.colors.find(c=>c.id===v.color)?.name)}</div><div class="swatches" role="group" aria-labelledby="color-label">${[...new Set(p.variants.filter(x=>x.size===v.size).map(v=>v.color))].map(c=>{const color=state.catalog.colors.find(x=>x.id===c);return `<button aria-pressed="${v.color===c}" class="swatch ${v.color===c?'selected':''}" style="--swatch:${esc(color.hex)}" data-action="product-color" data-id="${c}" aria-label="${esc(color.name)}"></button>`;}).join('')}</div>${customPreview ? `<a class="btn btn-outline full gift-config-edit" data-native href="${giftStudioURL(p.id, null, v)}">Настроить героев ${icon('arrow')}</a>` : ''}<div class="quantity-label"><label>Количество копий</label>${quantityControl(state.productQty,'product-quantity')}</div><div class="discount-hint">${discountHint()}<small>Скидки действуют на одинаковый вариант композиции.</small></div><div id="product-price" aria-live="polite">${priceSummary(state.quote)}</div><button class="btn btn-dark full" data-action="product-add" ${v.stock<=0?'disabled':''}>${v.stock>0?(state.cartEditId&&state.cartEditMode==='product'?'Сохранить изменения':'Добавить в корзину'):'Нет в наличии'} ${icon('bag')}</button><div class="detail-facts"><span>${icon('frame')} Пластиковая рамка глубиной 45 мм</span><span>${icon('check')} ${esc(p.leadTime)}</span><span>${icon('heart')} Доставка уточняется при согласовании</span></div><details><summary>Что внутри композиции</summary><p>${p.count} персонажа, декоративный фон и рамка. Артикул варианта: ${esc(v.sku)}.${p.demo?' Комплектация тестовая.':''}</p></details></div></div></main>`;}
function empty(title,cta='Создать подарок',href='/catalog'){return `<main class="page wrap"><div class="empty">${icon('heart')}<h1>${esc(title)}</h1><p>Начните с маленькой истории о тех, кто вам дорог.</p><a class="btn btn-dark" href="${href}">${cta} ${icon('arrow')}</a></div></main>`;}
function cart(){if(!state.cart.length)return empty('Корзина пока пуста');return `<main class="wrap page"><div class="breadcrumbs"><a href="/">Главная</a> / Корзина</div><h1>Ваша корзина</h1><div class="cart-layout"><div class="cart-lines">${state.cart.map((l,i)=>{const p=l.type==='product'?state.catalog.products.find(p=>p.id===l.productId):null,v=p?.variants.find(v=>v.id===l.variantId),conf=l.config||(p&&getProductConfig(p,v));return `<article class="cart-line"><div class="cart-art">${conf?scene(conf,state.catalog):''}</div><div class="cart-line-copy"><span class="eyebrow">${l.type==='custom'?'Ваша композиция':'Готовый подарок'}</span><h3>${esc(l.name||p?.name||'Композиция')}</h3><p>${conf?.size||''} · ${esc(state.catalog.colors.find(c=>c.id===conf?.color)?.name||'')} · ${conf?.glazing==='glass'?'Стекло':'Пластиковое стекло'}</p>${quantityControl(l.quantity,'cart-quantity',String(i))}<button class="text-button cart-edit" data-action="cart-edit" data-id="${esc(l.clientId)}">${icon('frame')} ${l.type==='custom'?'Редактировать композицию':'Изменить размер и цвет'}</button><button class="text-button danger" data-action="cart-remove" data-id="${i}">Удалить</button></div><strong data-cart-total="${i}">${state.quote?.lines.find(x=>x.key===(l.type==='product'?'product:'+l.variantId:l.key))?.total?money(state.quote.lines.find(x=>x.key===(l.type==='product'?'product:'+l.variantId:l.key)).total):''}</strong></article>`;}).join('')}<a href="/catalog" class="text-link">${icon('plus')} Добавить ещё одну историю</a></div><aside class="order-summary"><h3>Ваш заказ</h3><label class="label" for="promo">Промокод</label><form id="promo-form" class="inline-form"><input id="promo" name="promo" placeholder="Если есть" value="${esc(state.promo)}"><button type="submit" class="icon-btn" aria-label="Применить промокод">${icon('arrow')}</button></form><div id="cart-price" aria-live="polite">${priceSummary(state.quote)}</div><p class="small muted">Стоимость доставки уточняется отдельно.</p><a href="/checkout" class="btn btn-dark full">Оформить заявку ${icon('arrow')}</a><p class="small" id="cart-mode-note">${state.session.user?.test||state.quote?.lines.some(l=>l.demo)?'Тестовая заявка — без оплаты и передачи в производство.':'Оплата после согласования.'}</p></aside></div></main>`;}
function checkout(){return `<main class="wrap page"><div class="narrow"><div class="eyebrow">Демонстрация оформления</div><h1>Оформление заявки</h1><p>На этом экране покупатель подтверждает почту, указывает контактные данные и выбирает доставку. Демоверсия не запрашивает данные и не отправляет заявки.</p><a class="btn btn-dark" href="/cart">Вернуться в корзину</a></div></main>`;}
function account(){if(!state.session.user)return `<main class="wrap page"><div class="narrow"><div class="eyebrow">Проекты и заказы</div><h1>Рады встрече.</h1><p>В рабочем магазине здесь будут сохранённые композиции, заявки и их статусы. Вход по почте в демоверсии выключен.</p><a class="btn btn-dark" href="/catalog">Смотреть рамки ${icon('arrow')}</a></div></main>`;return `<main class="wrap page"><div class="section-heading"><div><div class="eyebrow">${state.session.user.test?'Тестовый кабинет':'Личный кабинет'}</div><h1>${esc(state.session.user.name||'Мои истории')}</h1><p>${esc(state.session.user.email||state.session.user.phone||'')}</p></div><button class="text-button" data-action="logout">Выйти</button></div><h2>Сохранённые композиции</h2><div class="product-grid saved-grid">${state.projects.map((p,i)=>`<div class="saved-card"><div class="product-art palette-${i%4}">${scene(p.config,state.catalog)}</div><h3>${esc(p.name)}</h3><div class="button-row"><button class="btn btn-small btn-dark" data-action="project-open" data-id="${p.id}">Открыть</button><button class="icon-btn" data-action="project-copy" data-id="${p.id}" aria-label="Создать копию">${icon('copy')}</button><button class="icon-btn" data-action="project-delete" data-id="${p.id}" aria-label="Удалить проект">${icon('trash')}</button></div></div>`).join('')||'<div class="soft-notice">Пока ни одной сохранённой композиции. <a href="https://alinageminivolsip-ai.github.io/Mini-Brick-Studio/studio/" data-native>Создайте первую.</a></div>'}</div><h2 class="mt">История заказов</h2><div class="order-list">${state.orders.map(o=>`<article class="account-order"><div><span class="eyebrow">${esc(o.number)}</span><h3>${money(o.snapshot.total)}</h3><span class="small muted">${new Date(o.created_at).toLocaleDateString('ru-RU')}${o.snapshot.isTest?' · Тестовая заявка':''}</span></div><span class="status">${statusNames[o.status]}</span><div class="button-row"><button class="btn btn-dark btn-small" data-action="order-view" data-id="${o.id}">Посмотреть заказ</button><button class="btn btn-outline btn-small" data-action="order-repeat" data-id="${o.id}">Повторить</button></div></article>`).join('')||'<p class="muted">Здесь появятся ваши заявки и их статусы.</p>'}</div><div class="account-settings"><form id="profile-form" class="form-card"><h2>Личные настройки</h2><label>Имя<input name="name" maxlength="100" value="${esc(state.session.user.name)}"></label><p class="small muted">Фотографии не публикуются и не передаются внешним ИИ-сервисам. Рекламные рассылки не подключены.</p><p class="form-error" role="alert"></p><button class="btn btn-dark btn-small">Сохранить настройки</button></form><div class="form-card"><h2>Ваши данные</h2><p>Можно отозвать согласия или направить запрос на удаление данных. Заказы, которые требуется хранить, рассматриваются отдельно.</p><div class="privacy-account-actions"><button type="button" class="text-button" data-action="privacy-export">Скачать мои данные</button><button type="button" class="text-button" data-action="privacy-withdraw">Отозвать согласие</button><button type="button" class="text-button danger" data-action="privacy-request">Запросить удаление данных</button></div><p class="small"><a href="/privacy" data-native>Права и порядок обработки обращений</a></p></div></div></main>`;}
function info(){const key=route.slice(1);const data={how:['Как всё устроено','От идеи до подарка — несколько понятных шагов.',`<div class="steps"><article><span>01</span><h3>Выберите основу</h3><p>Готовая композиция или своя история. Четыре размера рамок, два направления для прямоугольных форматов.</p></article><article><span>02</span><h3>Соберите персонажей</h3><p>Выберите детали, фон и надпись. В свободном режиме можно двигать персонажей мышью или пальцем.</p></article><article><span>03</span><h3>Отправьте заявку</h3><p>Сайт посчитает цену и скидку. После входа сохраните проект или отправьте заявку без онлайн-оплаты.</p></article></div><h2>Больше одинаковых подарков — ниже цена</h2><p>1–2 копии: базовая цена. 3–10 копий: скидка 30%. От 11 копий: скидка 50%. Разные композиции и разные варианты не складываются для получения скидки.</p>`],about:['Маленькие вещи. Настоящие чувства.','MIGLIK — мгновения, которые остаются.',`<p>Мы создаём персонализированные объёмные подарки: глубокие рамки с минифигурками, фонами и словами, которые имеют значение.</p><p>Каждая композиция начинается с истории: о любви, семье, дружбе или человеке, который рядом. Вы собираете её из деталей, а мы превращаем в вещь, которую хочется сохранить.</p><div class="soft-notice">Сейчас MIGLIK находится в закрытой разработке. Тестовые изображения — цифровые эскизы; реальные фотографии и ассортимент появятся после проверки производства.</div><h2>Сначала — подарки с минифигурками</h2><p>Памятные композиции и архитектурные макеты будут отдельными направлениями. Сейчас они не принимаются в заказ.</p>`],delivery:['Доставка и оплата','Сначала согласуем все детали.',`<h2>Заявка без онлайн-оплаты</h2><p>На первом этапе сайт принимает заявки. Стоимость и способ оплаты согласовываются после проверки комплектации. Онлайн-эквайринг пока не подключён.</p><h2>Как получить подарок</h2><p>В заявке можно указать пункт выдачи, курьера или самовывоз. Доступность, адрес, тариф и срок подтверждаются отдельно. Скидка на копии не распространяется на доставку.</p><h2>Срок изготовления</h2><p>Зависит от наличия деталей и объёма заказа. Подтверждённый срок сообщим при согласовании.</p>`],contacts:['Будем на связи.','Контакты мастерской скоро появятся здесь.',`<div class="soft-notice">Владелец ещё не добавил официальные телефон, почту, адрес и реквизиты. В закрытой версии можно проверить оформление тестовой заявки.</div><a href="/catalog" class="btn btn-dark">Выбрать подарок ${icon('arrow')}</a>`],legal:['Правовые документы','Подготовка к публичному запуску.',`<div class="soft-notice">Это раздел закрытой разработки. Юридические документы пока не утверждены владельцем и не являются публичной офертой.</div><h2 id="consent">Обработка данных</h2><p>Данные используются для входа, сохранения проекта и обработки заявки. Фотографии доступны владельцу и уполномоченному администратору. В закрытой версии используются тестовые заказы.</p><h2>Отдельные согласия</h2><p>Согласие на рекламные сообщения отделено от обработки заявки и не отмечается заранее. Публикация фотографий и передача их внешним ИИ-сервисам требуют самостоятельного решения.</p><h2>Перед реальными продажами</h2><p>Нужно добавить сведения об операторе, утверждённую политику обработки данных, сроки хранения, тексты согласий, правила возврата и условия продажи. Перечень для заполнения находится в документации проекта.</p><h2>Удаление данных</h2><p>В личном кабинете доступна отправка запроса владельцу сайта.</p>`]};if(key==='gallery')return `<main class="wrap page"><div class="eyebrow">НЕСКОЛЬКО ИДЕЙ ДЛЯ ВАШЕЙ ИСТОРИИ</div><h1>Галерея подарков MIGLIK</h1><p>Цифровые эскизы стартовой коллекции. Фотографии клиентов здесь не публикуются.</p><div class="product-grid">${state.catalog.products.map(productCard).join('')}</div></main>`;if(key==='contacts'&&state.catalog.settings.operatorName){const c=state.catalog.settings;data.contacts=['Контакты MIGLIK',c.operatorName,`<p>${esc(c.operatorEmail)}</p><p>${esc(c.operatorPhone)}</p><p>${esc(c.operatorAddress)}</p>`];}if(key==='legal'&&state.catalog.settings.legalApproved){const c=state.catalog.settings;data.legal=['Правовые документы','Версия '+c.legalVersion,`<h2>Оператор</h2><p>${esc(c.operatorName)}</p><h2>Политика обработки данных</h2><div class="legal-text">${esc(c.legalPolicy)}</div><h2>Условия продажи</h2><div class="legal-text">${esc(c.offerText)}</div><h2 id="consent">Согласие на обработку данных</h2><div class="legal-text">${esc(c.consentText)}</div>`];}const d=data[key]||data.about;return `<main class="wrap page info-page"><div class="eyebrow">MIGLIK · С ЛИЧНЫМ СМЫСЛОМ</div><h1>${d[0]}</h1><p class="lead">${d[1]}</p><div class="prose">${d[2]}</div></main>`;}
const ctx={state,esc,icon,money,api,toast,nav,persist,render,renderBuilder,cancelCartEdit,quantityControl,priceSummary,scene,demoConfig,field,discountHint,closeModal,modal,auth:openAuth,refreshCatalog:async()=>{state.catalog=await api('/api/catalog');},statusNames};
function render(){if(!state.catalog)return;state.mobileMenu=false;const content=route==='/'?home():route==='/catalog'||route.startsWith('/gifts/')?catalog():route.startsWith('/product/')?product():route==='/cart'?cart():route==='/checkout'?checkout():route==='/account'?account():info();document.title=(route==='/'?'Мгновения, которые остаются':route==='/builder'?'Создать подарок':route==='/admin'?'Мастерская MIGLIK':route==='/account'?'Личный кабинет':route==='/cart'?'Корзина':route==='/checkout'?'Оформление заявки':route.startsWith('/product/')?(state.catalog.products.find(p=>p.id===route.split('/').pop())?.name||'Подарок'):route==='/catalog'?'Готовые подарки':route.startsWith('/gifts/')?(occasions[route.split('/').pop()]||'Подарки'):'Мгновения, которые остаются')+' — MIGLIK';app.innerHTML=header()+content+(route==='/builder'?'':footer());const main=app.querySelector('main');if(main){main.id='main-content';main.tabIndex=-1;}rewriteLinks(app);if(route==='/builder')bindBuilder(ctx);}
function renderBuilder({resetControls=false}={}){
 const panel=document.querySelector('.builder-controls'),position={x:window.scrollX,y:window.scrollY,panel:resetControls?0:panel?.scrollTop||0};
 const active=document.activeElement;let selector=null,selection=null;
 if(active?.closest('.builder')){
  if(active.id)selector='#'+CSS.escape(active.id);
  else if(active.dataset.textField)selector=`${active.tagName.toLowerCase()}${active.tagName==='INPUT'?`[type="${active.type}"]`:''}[data-text-field="${CSS.escape(active.dataset.textField)}"][data-id="${CSS.escape(active.dataset.id||'')}"]`;
  else if(active.dataset.action)selector=`[data-action="${CSS.escape(active.dataset.action)}"]${active.dataset.id!==undefined?`[data-id="${CSS.escape(active.dataset.id)}"]`:''}${active.dataset.direction?`[data-direction="${CSS.escape(active.dataset.direction)}"]`:''}`;
  try{if(typeof active.selectionStart==='number')selection=[active.selectionStart,active.selectionEnd];}catch{}
 }
 render();const replacement=selector?document.querySelector(selector):null;
 if(replacement){replacement.focus({preventScroll:true});if(selection)try{replacement.setSelectionRange(...selection);}catch{}}
 const nextPanel=document.querySelector('.builder-controls');if(nextPanel)nextPanel.scrollTop=position.panel;window.scrollTo({left:position.x,top:position.y,behavior:'instant'});
}
function clearCartEdit(){state.cartEditId=null;state.cartEditMode=null;state.cartEditProductId=null;}
async function cancelCartEdit(){const item=state.cart.find(item=>item.clientId===state.cartEditId);if(item?.type==='custom'){state.draftChanged=true;state.draft=structuredClone(item.config);state.quantity=item.quantity;resetBuilderHistory();}clearCartEdit();persist();await nav('/cart');toast('Изменения не применены к корзине');}
async function refreshQuote(){const seq=++quoteSeq;try{let items;if(route.startsWith('/product/')){const p=state.catalog.products.find(p=>p.id===route.split('/').pop());if(!p)return;items=[{type:'product',productId:p.id,variantId:state.productVariant||p.variants[0].id,quantity:state.productQty}];}else if(route==='/builder')items=[{type:'custom',name:'Моя история MIGLIK',config:state.draft,quantity:state.quantity}];else if(['/cart','/checkout'].includes(route)){if(!state.cart.length)return;items=state.cart;}else return;
 persist();state.quoteError='';const q=await api('/api/quote',{items,promo:state.promo&&route!=='/builder'&&!route.startsWith('/product/')?state.promo:''});if(seq!==quoteSeq)return;state.quote=q;const modeNote=document.getElementById('cart-mode-note');if(modeNote)modeNote.textContent=state.session.user?.test||q.lines.some(l=>l.demo)?'Тестовая заявка — без оплаты и передачи в производство.':'Оплата после согласования.';if(['/cart','/checkout'].includes(route)&&q.itemKeys){state.cart.forEach((item,i)=>{if(item.type==='custom')item.key=q.itemKeys[i];});persist();}for(const id of ['product-price','cart-price','checkout-price','builder-price']){const el=document.getElementById(id);if(el)el.innerHTML=priceSummary(q,id==='builder-price');}document.querySelectorAll('[data-cart-total]').forEach(el=>{const item=state.cart[Number(el.dataset.cartTotal)],key=item.type==='product'?'product:'+item.variantId:item.key;const line=q.lines.find(l=>l.key===key);el.textContent=line?money(line.total):'';});const add=document.querySelector('[data-action="b-add"]');if(add)add.disabled=false;
 }catch(e){if(seq!==quoteSeq)return;state.quote=null;state.quoteError=e.message;for(const id of ['product-price','cart-price','checkout-price','builder-price']){const el=document.getElementById(id);if(el)el.innerHTML=`<p class="form-error">${esc(e.message)}</p>`;}const add=document.querySelector('[data-action="b-add"]');if(add)add.disabled=true;}}
ctx.refreshQuote=refreshQuote;
async function loadRoute(){if(state.cartEditId){const path=state.cartEditMode==='product'?'/product/'+state.cartEditProductId:'/builder';if(route!==path||!state.cart.some(i=>i.clientId===state.cartEditId)){clearCartEdit();persist();}}if(route==='/account'&&state.session.user){[state.projects,state.orders]=await Promise.all([api('/api/projects'),api('/api/orders')]);}if(route==='/admin'&&state.session.admin){state.adminData=await api('/api/admin/data');await loadWorkshopOrders(ctx);}if(route.startsWith('/product/')){const p=state.catalog.products.find(p=>p.id===route.split('/').pop());if(p?.variants.some(v=>v.id===history.state?.productVariant))state.productVariant=history.state.productVariant;else if(p&&!p.variants.some(v=>v.id===state.productVariant))state.productVariant=p.variants[0].id;}render();await refreshQuote();}
function modal(html,extraClass=''){if(!document.querySelector('.modal'))modalTrigger=document.activeElement;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${extraClass}" role="dialog" aria-modal="true" aria-label="MIGLIK"><button class="icon-btn modal-close" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button>${html}</section></div>`;document.body.classList.add('modal-open');app.inert=true;const privacy=document.getElementById('privacy-root');if(privacy)privacy.inert=true;setTimeout(()=>document.querySelector('.modal input,.modal button:not(.modal-close)')?.focus(),0);}
function closeModal(){clearTimeout(authTimer);document.querySelector('#modal-root').innerHTML='';document.body.classList.remove('modal-open');app.inert=false;const privacy=document.getElementById('privacy-root');if(privacy)privacy.inert=false;if(modalTrigger?.isConnected)modalTrigger.focus({preventScroll:true});modalTrigger=null;}
function openAuth(after){authAfter=typeof after==='function'?after:null;showEmailAuth();}
function showEmailAuth(){clearTimeout(authTimer);persist();modal(`<div class="modal-symbol">${icon('mail')}</div><div class="eyebrow">Личный кабинет</div><h2>Войти в MIGLIK</h2><p>Отправим одноразовый код на вашу электронную почту. Пароль не нужен.</p><form id="auth-form"><label>Электронная почта<input name="email" type="email" autocomplete="email" maxlength="254" value="${esc(state.authEmail)}" placeholder="name@example.ru" required></label><label class="checkbox"><input name="consent" type="checkbox" required><span>${esc(state.session.emailLoginConsent)} <a href="/consent/login" data-native target="_blank" rel="noopener">Подробнее</a></span></label><p class="form-error" role="alert"></p><button type="submit" class="btn btn-dark full" ${state.session.emailStatus?.enabled?'':'disabled'}>Получить код ${icon('arrow')}</button></form>${!state.session.emailStatus?.enabled?`<p class="small muted">${esc(state.session.emailStatus?.message||'Отправка писем пока не подключена.')}</p>`:''}${state.session.localTestLogin?'<div class="test-login"><span>Локальная проверка без отправки писем</span><button class="btn btn-outline full" data-action="test-login">Войти как тестировщик</button><small>Только на этом компьютере. Заказы будут тестовыми.</small></div>':''}`);}
async function requestEmailCode(){const result=await api('/api/auth/send',{email:state.authEmail,consent:true});state.authChallenge=result.challenge;state.authResendAt=Date.now()+result.resendAfter*1000;showEmailCode();}
function showEmailCode(){clearTimeout(authTimer);modal(`<div class="modal-symbol">${icon('mail')}</div><h2>Проверьте почту</h2><p>Код отправлен на <b>${esc(state.authEmail)}</b>. Он действует 5 минут.</p><p class="small muted">Если письма нет, проверьте папку «Спам».</p><form id="otp-form"><label>Код из письма<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></label><p class="form-error" role="alert"></p><button type="submit" class="btn btn-dark full">Войти</button></form><div class="button-row mt"><button type="button" class="text-button" data-action="auth-resend" disabled>Отправить код повторно</button><button type="button" class="text-button" data-action="auth-change">Другой адрес</button></div><p class="small muted" id="auth-resend-status" aria-live="polite"></p>`);const tick=()=>{const button=document.querySelector('[data-action="auth-resend"]'),status=document.querySelector('#auth-resend-status');if(!button)return;const seconds=Math.max(0,Math.ceil((state.authResendAt-Date.now())/1000));button.disabled=seconds>0;status.textContent=seconds?`Повторная отправка через ${seconds} сек.`:'';if(seconds)authTimer=setTimeout(tick,1000);};tick();}
async function addToCart(item){
 const editing=state.cartEditId&&item.type===state.cartEditMode,index=editing?state.cart.findIndex(line=>line.clientId===state.cartEditId):-1;
 if(editing&&index<0)throw Error('Редактируемая композиция уже удалена из корзины');
 const existing=state.cart.find((line,i)=>i!==index&&item.type===line.type&&(item.type==='product'?item.variantId===line.variantId:item.key===line.key));
 if(existing&&existing.quantity+item.quantity>state.catalog.settings.maxQuantity)throw Error('Превышено максимальное количество копий');
 if(existing){existing.quantity+=item.quantity;if(editing)state.cart.splice(index,1);}
 else if(editing)state.cart[index]={...item,clientId:state.cartEditId};
 else state.cart.push({...item,clientId:crypto.randomUUID()});
 if(editing)clearCartEdit();persist();toast(editing?'Изменения сохранены в корзине':'История добавлена в корзину');if(route==='/builder')renderBuilder();else render();
}

ctx.addToCart=addToCart;
document.addEventListener('click',async e=>{
 const link=e.target.closest('a[href]');if(link&&!e.ctrlKey&&!e.metaKey&&link.target!=='_blank'&&link.dataset.previewRoute&&!link.hasAttribute('download')&&!link.hasAttribute('data-native')&&!link.href.includes('/api/admin/download/')){e.preventDefault();try{if(link.dataset.startSize){if(!state.draft)state.draft=demoConfig(state.catalog,{size:link.dataset.startSize,title:'Наша история'});else await builderAction(ctx,'b-size',link.dataset.startSize,link);}await nav(link.dataset.previewRoute);}catch(err){toast(err.message);}return;}
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,key=b.dataset.id;
 try{
  if(await builderAction(ctx,action,key,b))return;if(await adminAction(ctx,action,key,b))return;
  if(action==='menu'){state.mobileMenu=!state.mobileMenu;const content=document.createElement('nav');content.className='mobile-nav';content.setAttribute('aria-label','Навигация магазина');content.id='mobile-navigation';b.setAttribute('aria-expanded',String(state.mobileMenu));if(state.mobileMenu){content.innerHTML='<a href="/catalog">Готовые подарки</a><a href="https://alinageminivolsip-ai.github.io/Mini-Brick-Studio/studio/" data-native>Создать подарок</a><a href="/#stories" data-native>Истории</a><a href="/delivery">Доставка и оплата</a><a href="/#faq" data-native>Вопросы</a><a href="/legal" data-native>Документы</a>';rewriteLinks(content);document.querySelector('.site-header').after(content);}else document.querySelector('.mobile-nav')?.remove();}
  if(action==='filter'){state.filter=key;rememberCatalog();if(route.startsWith('/gifts/'))await nav('/catalog');else{render();restoreControl(b);}}
  if(action==='product-size'||action==='product-color'){const p=state.catalog.products.find(p=>p.id===route.split('/').pop()),old=p.variants.find(v=>v.id===state.productVariant),v=p.variants.find(v=>action==='product-size'?v.size===key&&v.color===old.color:v.size===old.size&&v.color===key)||p.variants.find(v=>v.size===key);if(!v)return;state.productVariant=v.id;history.replaceState({...history.state,productVariant:v.id},'');state.quote=null;render();restoreControl(b);await refreshQuote();}
  if(action==='product-quantity'){state.productQty=Math.max(1,Math.min(state.catalog.settings.maxQuantity,state.productQty+Number(b.dataset.delta)));state.quote=null;render();restoreControl(b);await refreshQuote();}
  if(action==='product-add'){const editing=!!state.cartEditId&&state.cartEditMode==='product';const p=state.catalog.products.find(p=>p.id===route.split('/').pop());await addToCart({type:'product',productId:p.id,variantId:state.productVariant,quantity:state.productQty,name:p.name});if(editing)await nav('/cart');else await refreshQuote();}
  if(action==='cart-cancel-edit'){await cancelCartEdit();}
  if(action==='cart-edit'){const item=state.cart.find(i=>i.clientId===key);if(!item)throw Error('Композиция не найдена');state.cartEditId=item.clientId;state.cartEditMode=item.type;if(item.type==='custom'){state.draftChanged=true;state.draft=structuredClone(item.config);state.quantity=item.quantity;state.projectName=item.name;state.projectId=null;state.step='frame';state.selected=item.config.characters[0]?.id||'';resetBuilderHistory();persist();await nav('/builder');}else{state.cartEditProductId=item.productId;state.productVariant=item.variantId;state.productQty=item.quantity;persist();await nav('/product/'+item.productId);}}
  if(action==='cart-remove'){state.cart.splice(Number(key),1);persist();render();await refreshQuote();}
  if(action==='cart-quantity'){state.cart[Number(key)].quantity=Math.max(1,Math.min(state.catalog.settings.maxQuantity,state.cart[Number(key)].quantity+Number(b.dataset.delta)));persist();state.quote=null;render();restoreControl(b);await refreshQuote();}
  if(action==='auth')openAuth();
  if(action==='cookie-settings')location.href=previewURL('/cookies');
  if(action==='auth-change')showEmailAuth();
  if(action==='auth-resend'){b.disabled=true;try{await requestEmailCode();}catch(error){b.disabled=false;throw error;}}
  if(action==='close-modal')closeModal();
  if(action==='test-login'){state.session=await api('/api/auth/test',{});closeModal();if(authAfter){const after=authAfter;authAfter=null;await after();}else await loadRoute();toast('Вы вошли в тестовый кабинет');}
  if(action==='logout'){await api('/api/logout',{});state.session=await api('/api/session');await loadRoute();}
  if(action==='project-open'){const p=state.projects.find(p=>p.id===key);resetBuilderHistory();state.draftChanged=true;state.draft=structuredClone(p.config);state.projectId=p.id;state.projectName=p.name;persist();await nav('/builder');}
  if(action==='project-copy'){const p=state.projects.find(p=>p.id===key);await api('/api/projects',{name:p.name+' — копия',config:p.config});await loadRoute();toast('Копия сохранена');}
  if(action==='project-delete'){await api('/api/projects/'+key,{},'DELETE');await loadRoute();toast('Проект удалён');}
  if(action==='order-view'){const order=await api('/api/orders/'+key);modal(orderDetails(order,{money,statusNames}),'order-modal');}
  if(action==='order-repeat'){const o=state.orders.find(o=>o.id===key);state.cart.push(...o.snapshot.lines.map(l=>l.type==='product'?{clientId:crypto.randomUUID(),type:'product',productId:l.productId,variantId:l.variantId,quantity:l.quantity,name:l.name}:{clientId:crypto.randomUUID(),type:'custom',config:l.config,name:l.name,quantity:l.quantity,key:l.key}));persist();await nav('/cart');toast('Композиции добавлены. Цены и наличие пересчитаны.');}
  if(action==='privacy-request'||action==='privacy-withdraw'){const result=await api('/api/privacy-request',{kind:action==='privacy-withdraw'?'withdraw-consent':'delete'});toast(result.message);}
  if(action==='privacy-export'){const result=await api('/api/account/export'),url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='miglik-personal-data.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 }catch(err){toast(err.message);}
});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,formId=form.getAttribute('id'),data=Object.fromEntries(new FormData(form));const button=form.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=true;const error=form.querySelector('.form-error');if(error)error.textContent='';try{
 if(await adminSubmit(ctx,formId,data,form))return;
 if(formId==='auth-form'){state.authEmail=data.email.trim().toLowerCase();await requestEmailCode();}
 if(formId==='otp-form'){state.session=await api('/api/auth/verify',{challenge:state.authChallenge,code:data.code});closeModal();if(authAfter){const after=authAfter;authAfter=null;await after();}else await loadRoute();toast('Вы вошли в MIGLIK');}
 if(formId==='promo-form'){state.promo=(data.promo||'').trim().toUpperCase();await refreshQuote();}
 if(formId==='profile-form'){await api('/api/account',{name:data.name,publication:!!data.publication});state.session=await api('/api/session');toast('Настройки сохранены');}
 if(formId==='checkout-form'){assertQuote();const idempotency=sessionStorage.getItem('miglik.checkoutId')||crypto.randomUUID();sessionStorage.setItem('miglik.checkoutId',idempotency);const result=await api('/api/orders',{items:state.cart,promo:state.promo,fingerprint:state.quote.fingerprint,idempotency,customer:data,consent:!!data.consent,terms:!!data.terms});state.cart=[];state.quote=null;state.promo='';persist();sessionStorage.removeItem('miglik.checkoutId');await nav('/account');modal(`<div class="modal-symbol">${icon('check')}</div><div class="eyebrow">${result.isTest?'ТЕСТОВАЯ ЗАЯВКА СОХРАНЕНА':'ЗАЯВКА СОХРАНЕНА'}</div><h2>У истории есть начало.</h2><p>Номер ${esc(result.number)}. Она уже в вашем личном кабинете.</p>${result.productionStatus==='failed'?'<p class="form-error">Заявка сохранена. Архив требует повторной генерации администратором.</p>':''}<button class="btn btn-dark full" data-action="close-modal">Хорошо ${icon('heart')}</button>`);}
 }catch(err){if(error)error.textContent=err.message;else toast(err.message);}finally{if(button)button.disabled=false;}});
function assertQuote(){if(!state.quote)throw Error(state.quoteError||'Дождитесь расчёта цены');}
document.addEventListener('change',async e=>{try{if(await builderChange(ctx,e.target))return;if(await adminChange(ctx,e.target))return;const t=e.target;if(t.id==='catalog-search'){state.search=t.value;rememberCatalog();render();}if(t.dataset.quantityAction){const q=Math.max(1,Math.min(state.catalog.settings.maxQuantity,parseInt(t.value)||1));if(t.dataset.quantityAction==='product-quantity')state.productQty=q;else if(t.dataset.quantityAction==='cart-quantity'){state.cart[Number(t.dataset.qty)].quantity=q;persist();}render();await refreshQuote();}}catch(err){toast(err.message);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.querySelector('.modal'))closeModal();else if(state.mobileMenu){const toggle=document.querySelector('[data-action=menu]');toggle?.click();toggle?.focus();}}if(e.key==='Tab'&&document.querySelector('.modal')){const focusable=[...document.querySelectorAll('.modal button:not(:disabled),.modal input:not(:disabled):not([type=hidden]),.modal a[href],.modal select:not(:disabled),.modal textarea:not(:disabled)')];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0]?.focus();}}});
let quantityTimer,searchTimer;
document.addEventListener('input',e=>{const t=e.target;if(t.id==='inventory-search'){filterInventory();return;}if(builderInput(ctx,t))return;if(t.id==='catalog-search'){state.search=t.value;rememberCatalog();clearTimeout(searchTimer);const position=t.selectionStart;searchTimer=setTimeout(()=>{if(route!=='/catalog'&&!route.startsWith('/gifts/'))return;render();const input=document.getElementById('catalog-search');input?.focus();if(position!==null)input?.setSelectionRange(position,position);},180);return;}if(t.id==='admin-order-search'){document.querySelectorAll('[data-order-search]').forEach(row=>row.hidden=!row.dataset.orderSearch.includes(t.value.toLowerCase()));return;}const action=t.dataset.quantityAction;if(!action)return;const quantity=parseInt(t.value);if(!Number.isInteger(quantity)||quantity<1||quantity>state.catalog.settings.maxQuantity)return;if(action==='b-quantity')state.quantity=quantity;else if(action==='product-quantity')state.productQty=quantity;else if(action==='cart-quantity'){state.cart[Number(t.dataset.qty)].quantity=quantity;persist();}clearTimeout(quantityTimer);quantityTimer=setTimeout(refreshQuote,180);});
window.addEventListener('popstate',()=>{route=previewRoute();restoreCatalog();closeModal();loadRoute().then(focusContent).catch(e=>toast(e.message));});
try{restoreCatalog();state.session=await api('/api/session');state.catalog=await api('/api/catalog');await loadRoute();}catch(e){app.innerHTML=`<main class="wrap page"><h1>Не удалось загрузить MIGLIK</h1><p>${esc(e.message)}</p><a href="/" class="btn btn-dark">Попробовать ещё раз</a></main>`;}

document.addEventListener('miglik-privacy-change',()=>{if(draftsAllowed()&&!state.draftChanged&&!state.cartEditId){const previousDraft=read('miglik.draft',null);if(previousDraft)state.draft=previousDraft;}persist();if(route==='/builder')renderBuilder();});
